namespace Rrp.Core;
public sealed class WorkflowValidator{
 static readonly HashSet<string> Classes=new(StringComparer.OrdinalIgnoreCase){"read","write","destructive","credential","external-communication","financial"};
 public ValidationResult Validate(RrpWorkflow w){var issues=new List<ValidationIssue>();if(w.ApiVersion!="rrp.dev/v1")issues.Add(new("unsupported_version","apiVersion must be rrp.dev/v1."));if(w.Kind!="Workflow")issues.Add(new("invalid_kind","kind must be Workflow."));if(string.IsNullOrWhiteSpace(w.Metadata.Id))issues.Add(new("missing_id","metadata.id is required."));if(w.Steps.Count==0)issues.Add(new("missing_steps","At least one step is required."));var ids=new HashSet<string>();foreach(var s in w.Steps){if(!ids.Add(s.Id))issues.Add(new("duplicate_step_id",$"Duplicate step '{s.Id}'.",s.Id));if(s.TimeoutMs is <1 or >300000)issues.Add(new("invalid_timeout","timeoutMs out of range.",s.Id));if(s.Target is {Candidates.Count:0})issues.Add(new("missing_selector","Target needs selectors.",s.Id));if(s.Approval is not null&&!Classes.Contains(s.Approval.Class))issues.Add(new("invalid_approval_class","Unknown approval class.",s.Id));if(Mutates(s.Action)&&s.Postconditions is null)issues.Add(new("missing_postcondition","Mutating steps need a postcondition.",s.Id));}return new(issues.Count==0,issues);}
 static bool Mutates(string a)=>new[]{"click","set","type","upload","submit"}.Any(v=>a.Contains(v,StringComparison.OrdinalIgnoreCase));
}
